//! 🛫️ Literal flat GIS native records with complete borrowed entity admission.
use super::*;
use semio_framework_value::NativeEncodeControl;
fn child_paid<S>(value:&store::ArtifactChild<S>,c:&mut NativeEncodeControl<'_>)->Result<Child,semio_framework_value::ValueError>{Ok(Child{child_id:c.copy_text(&value.child_id)?,artifact_id:c.copy_text(&value.target.artifact_id)?,artifact_kind:c.copy_text(&value.target.dialect.artifact_kind)?,standard:c.copy_text(&value.target.dialect.standard)?,subset:c.copy_text(&value.target.dialect.subset)?})}
fn add(rows:&mut usize,count:usize,maximum:usize)->Result<(),semio_framework_value::ValueError>{*rows=rows.checked_add(count).filter(|rows|*rows<=maximum).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"GIS native semantic row limit exceeded"))?;Ok(())}
fn frontier<'a>(snapshot:&'a GisMapSnapshot,maximum:usize,c:&mut NativeEncodeControl<'_>)->Result<Vec<&'a semio_framework_value::DslValue>,semio_framework_value::ValueError>{c.scoped_stage(|c|{
 c.begin_stage(0)?;let count=snapshot.positions.len().checked_add(snapshot.routes.len()).and_then(|n|n.checked_add(snapshot.regions.len())).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"GIS feature count overflow"))?;let mut rows=3+usize::from(snapshot.image.is_some());add(&mut rows,count,maximum)?;let minimum=rows.checked_add(count.checked_mul(2).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"GIS native row count overflow"))?).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"GIS native row count overflow"))?;if minimum>maximum{return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"GIS native semantic row limit exceeded"))}
 let mut values=c.allocate_vec(count)?;c.scoped_stage(|c|{c.begin_stage(count)?;for feature in snapshot.positions.iter().chain(&snapshot.routes).chain(&snapshot.regions){values.push(&feature.data);c.step()?;}Ok::<_,semio_framework_value::ValueError>(())})?;let mut index=0;while index<values.len(){let value=values[index];add(&mut rows,2,maximum)?;let children=match value{semio_framework_value::DslValue::Array(values)=>values.len(),semio_framework_value::DslValue::Object(values)=>values.len(),_=>0};add(&mut rows,if let semio_framework_value::DslValue::Bytes(bytes)=value{bytes.len()}else{children},maximum)?;let minimum=values.len().checked_sub(index+1).and_then(|n|n.checked_add(children)).and_then(|n|n.checked_mul(2)).and_then(|n|n.checked_add(rows)).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"GIS native row count overflow"))?;if minimum>maximum{return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"GIS native semantic row limit exceeded"))}let required=values.len().checked_add(children).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"GIS frontier overflow"))?;if required>values.capacity(){c.charge((required-values.capacity()).checked_mul(std::mem::size_of::<&semio_framework_value::DslValue>()).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"GIS frontier allocation overflow"))?)?;values.try_reserve_exact(required-values.len()).map_err(|_|semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::AllocationFailed,"GIS frontier allocation failed"))?;}c.scoped_stage(|c|{c.begin_stage(children)?;match value{semio_framework_value::DslValue::Array(items)=>for item in items{values.push(item);c.step()?;},semio_framework_value::DslValue::Object(items)=>for(_,item)in items{values.push(item);c.step()?;},_=>{}}Ok::<_,semio_framework_value::ValueError>(())})?;index+=1;c.step()?;}Ok(values)
})}
fn features_paid(values:&[MapFeature],next:&mut u64,c:&mut NativeEncodeControl<'_>)->Result<Vec<Feature>,semio_framework_value::ValueError>{c.scoped_stage(|c|{c.begin_stage(values.len())?;let mut out=c.allocate_vec(values.len())?;for feature in values{let value=*next;*next=next.checked_add(1).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"GIS native Value identity overflow"))?;out.push(Feature{id:c.copy_text(&feature.id)?,value});c.step()?;}Ok(out)})}
pub(super) fn project(snapshot:&GisMapSnapshot,maximum:usize,c:&mut NativeEncodeControl<'_>)->Result<semio_framework_dsl_record::RecordValue,semio_framework_value::ValueError>{let result=(||->Result<semio_framework_dsl_record::RecordValue,semio_framework_value::ValueError>{
 let source=frontier(snapshot,maximum,c)?;let mut next=0;let positions=features_paid(&snapshot.positions,&mut next,c)?;let routes=features_paid(&snapshot.routes,&mut next,c)?;let regions=features_paid(&snapshot.regions,&mut next,c)?;c.begin_stage(source.len())?;let mut values=c.allocate_vec(source.len())?;
 for value in source{let mut node=Value{kind:Kind::Null,boolean:None,unsigned:None,signed:None,float:None,text:None,bytes:None,items:Vec::new(),members:Vec::new()};match value{
  semio_framework_value::DslValue::Null=>{},semio_framework_value::DslValue::Bool(value)=>{node.kind=Kind::Boolean;node.boolean=Some(*value)},
  semio_framework_value::DslValue::Number(Number::UInt(value))=>{node.kind=Kind::Unsigned;node.unsigned=Some(*value)},semio_framework_value::DslValue::Number(Number::Int(value))=>{node.kind=Kind::Signed;node.signed=Some(*value)},semio_framework_value::DslValue::Number(Number::Float(value))=>{node.kind=Kind::Float;node.float=Some(*value)},
  semio_framework_value::DslValue::String(value)=>{node.kind=Kind::Text;node.text=Some(c.copy_text(value)?)},semio_framework_value::DslValue::Bytes(value)=>{node.kind=Kind::Bytes;node.bytes=Some(Octets(c.copy_bytes(value)?))},
  semio_framework_value::DslValue::Array(items)=>{node.kind=Kind::Array;node.items=c.allocate_vec(items.len())?;c.scoped_stage(|c|{c.begin_stage(items.len())?;for _ in items{node.items.push(next);next=next.checked_add(1).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"GIS native Value identity overflow"))?;c.step()?;}Ok::<_,semio_framework_value::ValueError>(())})?;},
  semio_framework_value::DslValue::Object(members)=>{node.kind=Kind::Object;node.members=c.allocate_vec(members.len())?;c.scoped_stage(|c|{c.begin_stage(members.len())?;for(name,_)in members{node.members.push(Member{name:c.copy_text(name)?,value:next});next=next.checked_add(1).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"GIS native Value identity overflow"))?;c.step()?;}Ok::<_,semio_framework_value::ValueError>(())})?;}
 }values.push(node);c.step()?;}
 let record=Map{positions,routes,regions,drawing:child_paid(&snapshot.drawing,c)?,image:snapshot.image.as_ref().map(|value|child_paid(value,c)).transpose()?,value:child_paid(&snapshot.value,c)?,values};record.__dsl_to_record_controlled(c)
})();result}
